/**
 * Web Push over WebCrypto + fetch, so it runs on Node 24 and on Cloudflare Workers alike (the
 * `web-push` package needs node:https and friends). Two RFCs:
 * - RFC 8291 / RFC 8188: the payload is encrypted with `aes128gcm` for the browser's p256dh key
 *   and auth secret (ECDH P-256 + HKDF-SHA256 + AES-128-GCM, one record).
 * - RFC 8292 (VAPID): an ES256 JWT that tells the push service who is sending.
 * Keys use web-push's format (base64url: 65-byte uncompressed public point, 32-byte private
 * scalar), so keys generated by the old sender keep working and no subscription breaks.
 */

export interface VapidKeys {
  publicKey: string;
  privateKey: string;
}

export interface PushTarget {
  endpoint: string;
  keys: { p256dh: string; auth: string };
}

export interface SendOptions {
  /** Seconds the push service may hold the message. */
  ttl?: number;
  urgency?: 'very-low' | 'low' | 'normal' | 'high';
  fetch?: typeof fetch;
  now?: () => number;
}

/** Thrown when the push service refuses; 404/410 mean the subscription is gone. */
export class PushError extends Error {
  constructor(
    readonly statusCode: number,
    message: string,
  ) {
    super(message);
    this.name = 'PushError';
  }
}

/**
 * The slice of SubtleCrypto used here, typed loosely on purpose: this file is type-checked both
 * against @types/node (server) and against workerd's runtime types (apps/worker), whose WebCrypto
 * declarations disagree in details (workerd's d.ts even calls ECDH's `public` `$public`).
 */
type Key = object;
interface Jwk {
  kty: string;
  crv?: string;
  x?: string;
  y?: string;
  d?: string;
  ext?: boolean;
}
interface Subtle {
  importKey(
    format: 'raw' | 'jwk',
    data: Uint8Array | Jwk,
    algorithm: string | object,
    extractable: boolean,
    usages: string[],
  ): Promise<Key>;
  exportKey(format: 'raw', key: Key): Promise<ArrayBuffer>;
  exportKey(format: 'jwk', key: Key): Promise<Jwk>;
  generateKey(
    algorithm: object,
    extractable: boolean,
    usages: string[],
  ): Promise<{ publicKey: Key; privateKey: Key }>;
  deriveBits(algorithm: object, key: Key, length: number): Promise<ArrayBuffer>;
  encrypt(algorithm: object, key: Key, data: Uint8Array): Promise<ArrayBuffer>;
  sign(algorithm: object, key: Key, data: Uint8Array): Promise<ArrayBuffer>;
}
const subtle = (): Subtle => crypto.subtle as unknown as Subtle;

const RECORD_SIZE = 4096;
const enc = new TextEncoder();

export function b64urlEncode(bytes: Uint8Array): string {
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function b64urlDecode(s: string): Uint8Array<ArrayBuffer> {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function concat(...parts: Uint8Array[]): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) {
    out.set(p, at);
    at += p.length;
  }
  return out;
}

async function hkdf(
  salt: Uint8Array,
  ikm: Uint8Array,
  info: Uint8Array,
  length: number,
): Promise<Uint8Array<ArrayBuffer>> {
  const key = await subtle().importKey('raw', Uint8Array.from(ikm), 'HKDF', false, ['deriveBits']);
  const bits = await subtle().deriveBits(
    { name: 'HKDF', hash: 'SHA-256', salt: Uint8Array.from(salt), info: Uint8Array.from(info) },
    key,
    length * 8,
  );
  return new Uint8Array(bits);
}

/** A P-256 key pair as JWK pieces from web-push's raw base64url format. */
function p256Jwk(publicKey: Uint8Array, privateKey?: Uint8Array): Jwk {
  if (publicKey.length !== 65 || publicKey[0] !== 4) throw new Error('bad P-256 public key');
  return {
    kty: 'EC',
    crv: 'P-256',
    x: b64urlEncode(publicKey.slice(1, 33)),
    y: b64urlEncode(publicKey.slice(33, 65)),
    ...(privateKey ? { d: b64urlEncode(privateKey) } : {}),
    ext: true,
  };
}

/** New VAPID keys, in web-push's format. */
export async function generateVapidKeys(): Promise<VapidKeys> {
  const pair = await subtle().generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, [
    'sign',
    'verify',
  ]);
  const raw = new Uint8Array(await subtle().exportKey('raw', pair.publicKey));
  const jwk = await subtle().exportKey('jwk', pair.privateKey);
  return { publicKey: b64urlEncode(raw), privateKey: jwk.d! };
}

export interface EncryptOptions {
  /** Test hooks: a fixed sender key pair and salt reproduce RFC 8291's example. */
  senderKeys?: { publicKey: Uint8Array; privateKey: Uint8Array };
  salt?: Uint8Array;
}

/** RFC 8291 `aes128gcm` body for one subscription: header (salt, rs, keyid) + one record. */
export async function encryptPayload(
  target: PushTarget['keys'],
  plaintext: string | Uint8Array,
  opts: EncryptOptions = {},
): Promise<Uint8Array<ArrayBuffer>> {
  const uaPublic = b64urlDecode(target.p256dh);
  const authSecret = b64urlDecode(target.auth);
  const ecdh = { name: 'ECDH', namedCurve: 'P-256' } as const;

  let asPrivate: Key;
  let asPublic: Uint8Array;
  if (opts.senderKeys) {
    asPublic = opts.senderKeys.publicKey;
    asPrivate = await subtle().importKey(
      'jwk',
      p256Jwk(asPublic, opts.senderKeys.privateKey),
      ecdh,
      false,
      ['deriveBits'],
    );
  } else {
    const pair = await subtle().generateKey(ecdh, true, ['deriveBits']);
    asPrivate = pair.privateKey;
    asPublic = new Uint8Array(await subtle().exportKey('raw', pair.publicKey));
  }
  const uaKey = await subtle().importKey('raw', uaPublic, ecdh, false, []);
  const ecdhSecret = new Uint8Array(
    await subtle().deriveBits({ name: 'ECDH', public: uaKey }, asPrivate, 256),
  );

  // RFC 8291 section 3.4
  const keyInfo = concat(enc.encode('WebPush: info\0'), uaPublic, asPublic);
  const ikm = await hkdf(authSecret, ecdhSecret, keyInfo, 32);
  const salt = opts.salt ?? crypto.getRandomValues(new Uint8Array(16));
  const cek = await hkdf(salt, ikm, enc.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, enc.encode('Content-Encoding: nonce\0'), 12);

  const body = typeof plaintext === 'string' ? enc.encode(plaintext) : plaintext;
  // One record: the payload plus the 0x02 "last record" delimiter, no padding.
  if (body.length + 1 + 16 > RECORD_SIZE) throw new Error('push payload too large');
  const key = await subtle().importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const ct = new Uint8Array(
    await subtle().encrypt({ name: 'AES-GCM', iv: nonce }, key, concat(body, Uint8Array.of(2))),
  );

  const header = new Uint8Array(16 + 4 + 1 + asPublic.length);
  header.set(salt, 0);
  new DataView(header.buffer).setUint32(16, RECORD_SIZE);
  header[20] = asPublic.length;
  header.set(asPublic, 21);
  return concat(header, ct);
}

/** RFC 8292 `Authorization` header value: `vapid t=<ES256 JWT>, k=<public key>`. */
export async function vapidAuthorization(
  endpoint: string,
  vapid: VapidKeys & { subject: string },
  now = Date.now(),
): Promise<string> {
  const publicKey = b64urlDecode(vapid.publicKey);
  const key = await subtle().importKey(
    'jwk',
    p256Jwk(publicKey, b64urlDecode(vapid.privateKey)),
    { name: 'ECDSA', namedCurve: 'P-256' },
    false,
    ['sign'],
  );
  const part = (o: object) => b64urlEncode(enc.encode(JSON.stringify(o)));
  const unsigned = `${part({ typ: 'JWT', alg: 'ES256' })}.${part({
    aud: new URL(endpoint).origin,
    exp: Math.floor(now / 1000) + 12 * 3600,
    sub: vapid.subject,
  })}`;
  // WebCrypto's ECDSA signature is already the raw r||s form JWS wants.
  const sig = new Uint8Array(
    await subtle().sign({ name: 'ECDSA', hash: 'SHA-256' }, key, enc.encode(unsigned)),
  );
  return `vapid t=${unsigned}.${b64urlEncode(sig)}, k=${vapid.publicKey}`;
}

/** Encrypt and POST one notification. Resolves on 2xx; throws PushError otherwise. */
export async function sendWebPush(
  target: PushTarget,
  payload: string,
  vapid: VapidKeys & { subject: string },
  opts: SendOptions = {},
): Promise<void> {
  const doFetch = opts.fetch ?? fetch;
  const body = await encryptPayload(target.keys, payload);
  const res = await doFetch(target.endpoint, {
    method: 'POST',
    headers: {
      'content-encoding': 'aes128gcm',
      'content-type': 'application/octet-stream',
      ttl: String(opts.ttl ?? 3600),
      urgency: opts.urgency ?? 'high',
      authorization: await vapidAuthorization(target.endpoint, vapid, (opts.now ?? Date.now)()),
    },
    body,
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new PushError(res.status, `push service answered ${res.status}: ${text.slice(0, 200)}`);
  }
}
